-- Design pass (October 24): profile pictures, comment likes and replies, saved meals, FAQ,
-- and program text that says "you". Safe to run more than once.

-- 1. Profile pictures. Public bucket so pictures load fast everywhere; each person writes only her own folder.
alter table public.profiles add column if not exists avatar_path text;
insert into storage.buckets (id, name, public) values ('avatars', 'avatars', true)
on conflict (id) do update set public = true;
drop policy if exists "avatars write" on storage.objects;
drop policy if exists "avatars update" on storage.objects;
drop policy if exists "avatars delete" on storage.objects;
create policy "avatars write" on storage.objects for insert
  with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "avatars update" on storage.objects for update
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "avatars delete" on storage.objects for delete
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);
create or replace view public.member_names with (security_invoker = false) as
  select id, full_name, role, avatar_path from public.profiles;
grant select on public.member_names to authenticated;

-- 2. Community: reply to a comment, and like comments.
alter table public.comments add column if not exists parent_id uuid references public.comments (id) on delete cascade;
create table if not exists public.comment_likes (
  comment_id uuid references public.comments (id) on delete cascade,
  user_id uuid references public.profiles (id) on delete cascade,
  primary key (comment_id, user_id)
);
alter table public.comment_likes enable row level security;
drop policy if exists "members read comment likes" on public.comment_likes;
drop policy if exists "own comment likes" on public.comment_likes;
create policy "members read comment likes" on public.comment_likes for select using (auth.uid() is not null);
create policy "own comment likes" on public.comment_likes for all using (user_id = auth.uid()) with check (user_id = auth.uid());
do $$ begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and tablename = 'comment_likes') then
    alter publication supabase_realtime add table public.comment_likes;
  end if;
end $$;

-- 3. Saved meals ("go-to meals"): the table exists; add when she last used it, for ordering.
alter table public.saved_meals add column if not exists last_used_at timestamptz;
alter table public.saved_meals add column if not exists created_at timestamptz not null default now();

-- 4. FAQ: Michael's questions with video answers, plus shopping, supplement and gear lists with buy links.
create table if not exists public.faq_sections (
  id uuid primary key default gen_random_uuid(),
  slug text unique,
  title text not null,
  intro text,
  sort int not null default 0
);
create table if not exists public.faq_items (
  id uuid primary key default gen_random_uuid(),
  section_id uuid not null references public.faq_sections (id) on delete cascade,
  kind text not null default 'qa' check (kind in ('qa', 'list')),
  title text not null,
  body text,
  video_url text,
  links jsonb not null default '[]',   -- [{label, note, url}]
  sort int not null default 0
);
alter table public.faq_sections enable row level security;
alter table public.faq_items enable row level security;
drop policy if exists "read faq sections" on public.faq_sections;
drop policy if exists "coach writes faq sections" on public.faq_sections;
drop policy if exists "read faq items" on public.faq_items;
drop policy if exists "coach writes faq items" on public.faq_items;
create policy "read faq sections" on public.faq_sections for select using (auth.uid() is not null);
create policy "coach writes faq sections" on public.faq_sections for all using (public.is_coach()) with check (public.is_coach());
create policy "read faq items" on public.faq_items for select using (auth.uid() is not null);
create policy "coach writes faq items" on public.faq_items for all using (public.is_coach()) with check (public.is_coach());

-- FAQ starter content (drafted from Michael's docs; he edits it in the app). Only inserts what isn't there yet.
insert into public.faq_sections (id, slug, title, intro, sort) values ('91fb95ed-313d-55f6-91cb-cc94c6152e34', 'questions', 'Questions', 'Quick answers from Michael. Tap Watch for the video.', 0) on conflict (id) do nothing;
insert into public.faq_items (id, section_id, kind, title, body, links, sort) values ('009df808-5a91-582e-93d6-543b2e48d73f', '91fb95ed-313d-55f6-91cb-cc94c6152e34', 'qa', 'Why do I wake up at 3 AM, and what do I do about it?', 'Your night starts at 6 AM. The 3-Hour Window (outside light within 30 minutes, 40 g+ protein within an hour, moving within 2 hours, no caffeine for 90 minutes) resets your rhythm. When you do wake up, use the Blinking Method instead of grabbing your phone.', '[]'::jsonb, 0) on conflict (id) do nothing;
insert into public.faq_items (id, section_id, kind, title, body, links, sort) values ('15cc5fcd-4094-5cc4-b7e4-3fc578957d11', '91fb95ed-313d-55f6-91cb-cc94c6152e34', 'qa', 'When can I have my coffee?', 'No caffeine for the first 90 minutes after you wake up. Your cutoff is 10 hours before bed, and 300 mg a day at most across coffee, pre-workout and yerba mate.', '[]'::jsonb, 1) on conflict (id) do nothing;
insert into public.faq_items (id, section_id, kind, title, body, links, sort) values ('03d04d64-eaab-57a3-8382-9604e3ef66e6', '91fb95ed-313d-55f6-91cb-cc94c6152e34', 'qa', 'How much protein do I need?', '1 gram per pound of your goal weight, and never less than 120 g a day. That''s 40 g+ at each of your 3 meals, with breakfast within 60 minutes of waking. Eat the protein first.', '[]'::jsonb, 2) on conflict (id) do nothing;
insert into public.faq_items (id, section_id, kind, title, body, links, sort) values ('808f0401-db64-5bed-97bb-ac3484f2baa3', '91fb95ed-313d-55f6-91cb-cc94c6152e34', 'qa', 'Can I snack between meals?', 'Three meals a day, no snacks. Every meal gets 40 g+ protein and 10 g+ fiber, which keeps your blood sugar steady until the next one. If you''re hungry between meals, tell me in your check-in: it usually means a meal needs more protein or more volume.', '[]'::jsonb, 3) on conflict (id) do nothing;
insert into public.faq_items (id, section_id, kind, title, body, links, sort) values ('17af6390-26c2-5a5d-89bf-0b612aeff6d4', '91fb95ed-313d-55f6-91cb-cc94c6152e34', 'qa', 'Do I really have to log everything?', 'Yes. Calories always matter, and you can''t fix what you don''t see. Snap a photo or just say what you ate on the Food tab: it takes 20 seconds. Log the tiny calories too: oil, butter, sauces, bites.', '[]'::jsonb, 4) on conflict (id) do nothing;
insert into public.faq_items (id, section_id, kind, title, body, links, sort) values ('3196b807-ebf9-55fa-b921-61eba0b46bc4', '91fb95ed-313d-55f6-91cb-cc94c6152e34', 'qa', 'Why isn''t the scale moving?', 'First check the basics: are you weighing in daily and logging ingredient by ingredient, including oils and sauces? Scale weight bounces with water, salt and sleep, so look at the trend over 2 weeks, not one day. If the trend is flat for 2–3 weeks, I''ll adjust your calories in your check-in reply.', '[]'::jsonb, 5) on conflict (id) do nothing;
insert into public.faq_items (id, section_id, kind, title, body, links, sort) values ('7b3be0d7-fed1-5543-a7ed-0ddd1f6d5ad6', '91fb95ed-313d-55f6-91cb-cc94c6152e34', 'qa', 'What''s a diet break?', 'One week at maintenance calories after 8–12 weeks in a deficit (Weeks 8, 16 and 24). You keep logging and keep 40 g+ protein per meal. It protects your metabolism and your muscle, and it makes the next weeks of fat loss easier.', '[]'::jsonb, 6) on conflict (id) do nothing;
insert into public.faq_items (id, section_id, kind, title, body, links, sort) values ('e7ae9b7d-cd35-5ac9-8272-0dd005dec540', '91fb95ed-313d-55f6-91cb-cc94c6152e34', 'qa', 'Should I do intermittent fasting?', 'No. It works against the 3-Hour Window: breakfast with 40 g+ protein within an hour of waking is one of the things that fixes your sleep and your 3 PM crash.', '[]'::jsonb, 7) on conflict (id) do nothing;
insert into public.faq_items (id, section_id, kind, title, body, links, sort) values ('36574e30-7042-51e9-aee6-5342c77fcee6', '91fb95ed-313d-55f6-91cb-cc94c6152e34', 'qa', 'How do medals and CPs work?', 'Each circle is made of medals. A daily habit is done after a 14-day streak; a weekly one after 2 weeks in a row. Finish every habit in a medal and you earn 50 CPs; finish the whole circle for 250. Every habit you check off is 1 CP, and an on-time check-in is 10.', '[]'::jsonb, 8) on conflict (id) do nothing;
insert into public.faq_items (id, section_id, kind, title, body, links, sort) values ('6748b60f-893b-51d6-b8d5-24ed866d1aad', '91fb95ed-313d-55f6-91cb-cc94c6152e34', 'qa', 'When is my check-in due?', 'It opens Friday and closes Monday at noon Pacific. It takes 3–4 minutes, and I reply to every one personally.', '[]'::jsonb, 9) on conflict (id) do nothing;
insert into public.faq_items (id, section_id, kind, title, body, links, sort) values ('bdba3397-21f1-5a38-8e30-8112d0bd23cc', '91fb95ed-313d-55f6-91cb-cc94c6152e34', 'qa', 'I''m traveling or have an event coming up. What do I do?', 'Tell me in your check-in or send me a message. I''ll open the Travel or Holidays & Events fix-it for you: a short plan for before, during and after.', '[]'::jsonb, 10) on conflict (id) do nothing;
insert into public.faq_sections (id, slug, title, intro, sort) values ('da1d9f25-25d2-54e8-a459-fbfdad9e705e', 'shopping', 'Shopping list', 'What''s always in a Driven woman''s kitchen. Buy links added by Michael.', 1) on conflict (id) do nothing;
