insert into public.faq_items (id, section_id, kind, title, body, links, sort) values ('14e5d02b-26c1-5bb4-aadb-79c2ac838686', 'da1d9f25-25d2-54e8-a459-fbfdad9e705e', 'list', 'Fats', 'Enough for your hormones, within your calories.', '[{"label": "Flaxseed oil", "note": "1 tbsp daily", "url": ""}, {"label": "Olive oil", "note": "log it: 120 calories a tablespoon", "url": ""}, {"label": "Avocado", "note": null, "url": ""}]'::jsonb, 3) on conflict (id) do nothing;
